window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1dfc1b849ffda29d"]={"versions": [{"id": "FIG-1dfc1b849ffda29d", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm des AUTOSAR-System-Templates (Bereich <code>CoreCommunication</code>). Das Metamodell definiert die Signalübertragung und das Timing-Verhalten auf Netzwerkebene durch <code>ISignalTriggering</code>. Es stellt die Verbindung zwischen Kommunikationsports, logischen Signalen und Auslöse-/Wiederholungsmechanismen her.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ISignalTriggering</code> (Spezialisierung von <code>Identifiable</code>): Zentrales Element zur Zuordnung und Auslösung eines Signals.\n<ul class=\"fig-list\"><li>Assoziation <code>+signal</code>: Genau eine Zielinstanz von <code>CoreCommunication::ISignal</code> (spezialisiert <code>FibexElement</code>); Rückrichtung mit Multiplizität <code>1..*</code>.\n</li><li>Assoziation <code>+iSignalPort</code>: Beliebig viele Instanzen (<code>*</code>) von <code>CoreCommunication::SignalPort</code> (spezialisiert <code>CommConnectorPort</code>).\n</li><li>Komposition <code>+eventControlledTiming</code>: <code>0..1</code> Instanz von <code>EventControlledTiming</code>.\n</li><li>Komposition <code>+cyclicTiming</code>: <code>0..1</code> Instanz von <code>CyclicTiming</code>.\n</li></ul>\n</li><li><code>SignalPort</code> (aus <code>CoreCommunication</code>):\n<ul class=\"fig-list\"><li>Attribut <code>+ timeout: Float [0..1]</code> zur Festlegung des Empfangs- oder Sende-Timeouts.\n</li></ul>\n</li><li><code>ISignal</code> (aus <code>CoreCommunication</code>): Repräsentiert das FIBEX-kompatible Kommunikationssignal.\n</li><li><code>EventControlledTiming</code>:\n<ul class=\"fig-list\"><li>Attribut <code>+ numberOfRepeats: Int</code> definiert die Wiederholungsanzahl bei ereignisgesteuertem Senden.\n</li></ul>\n</li><li><code>CyclicTiming</code>:\n<ul class=\"fig-list\"><li>Attribut <code>+ finalRepetitions: Int [0..1]</code> definiert finale Wiederholungen beim Deaktivieren oder Beenden des zyklischen Sendens.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Darstellung dynamischer Sequenzen. Die Metaklassen beschreiben das Übertragungsverhalten von Signalen zur Laufzeit: Ein <code>ISignal</code> wird über <code>ISignalTriggering</code> an Ports (<code>SignalPort</code>) gebunden und kann entweder zyklisch (<code>CyclicTiming</code>) oder ereignisbasiert (<code>EventControlledTiming</code>) mit konfigurierbaren Wiederholungen getriggert werden. An Ports kann über <code>timeout</code> eine Überwachung konfiguriert werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation ist bindend für Werkzeuge und Generatoren zur Systembeschreibung (ARXML/FIBEX-Abbildung). Implementierer müssen beachten:</p>\n<ul class=\"fig-list\"><li>Ein <code>ISignalTriggering</code> referenziert zwingend genau ein <code>ISignal</code>, kann jedoch mehreren Ports zugeordnet sein.\n</li><li>Die Ausprägung von Timing-Mechanismen (<code>cyclicTiming</code>, <code>eventControlledTiming</code>) ist optional (Kardinalität <code>0..1</code>), schließt sich im Metamodell aber nicht gegenseitig aus.\n</li><li>Datentypen der Wiederholungszähler sind als <code>Int</code> und Timeouts als <code>Float</code> modelliert.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-fb4fa8449204bdbf", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm des AUTOSAR-System-Templates (Bereich <code>CoreCommunication</code>). Das Metamodell definiert die Signalübertragung und das Timing-Verhalten auf Netzwerkebene durch <code>ISignalTriggering</code>. Es stellt die Verbindung zwischen Kommunikationsports, logischen Signalen und Auslöse-/Wiederholungsmechanismen her.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ISignalTriggering</code> (Spezialisierung von <code>Identifiable</code>): Zentrales Element zur Zuordnung und Auslösung eines Signals.\n<ul class=\"fig-list\"><li>Assoziation <code>+signal</code>: Genau eine Zielinstanz von <code>CoreCommunication::ISignal</code> (spezialisiert <code>FibexElement</code>); Rückrichtung mit Multiplizität <code>1..*</code>.\n</li><li>Assoziation <code>+iSignalPort</code>: Beliebig viele Instanzen (<code>*</code>) von <code>CoreCommunication::SignalPort</code> (spezialisiert <code>CommConnectorPort</code>).\n</li><li>Komposition <code>+eventControlledTiming</code>: <code>0..1</code> Instanz von <code>EventControlledTiming</code>.\n</li><li>Komposition <code>+cyclicTiming</code>: <code>0..1</code> Instanz von <code>CyclicTiming</code>.\n</li></ul>\n</li><li><code>SignalPort</code> (aus <code>CoreCommunication</code>):\n<ul class=\"fig-list\"><li>Attribut <code>+ timeout: Float [0..1]</code> zur Festlegung des Empfangs- oder Sende-Timeouts.\n</li></ul>\n</li><li><code>ISignal</code> (aus <code>CoreCommunication</code>): Repräsentiert das FIBEX-kompatible Kommunikationssignal.\n</li><li><code>EventControlledTiming</code>:\n<ul class=\"fig-list\"><li>Attribut <code>+ numberOfRepeats: Int</code> definiert die Wiederholungsanzahl bei ereignisgesteuertem Senden.\n</li></ul>\n</li><li><code>CyclicTiming</code>:\n<ul class=\"fig-list\"><li>Attribut <code>+ finalRepetitions: Int [0..1]</code> definiert finale Wiederholungen beim Deaktivieren oder Beenden des zyklischen Sendens.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Darstellung dynamischer Sequenzen. Die Metaklassen beschreiben das Übertragungsverhalten von Signalen zur Laufzeit: Ein <code>ISignal</code> wird über <code>ISignalTriggering</code> an Ports (<code>SignalPort</code>) gebunden und kann entweder zyklisch (<code>CyclicTiming</code>) oder ereignisbasiert (<code>EventControlledTiming</code>) mit konfigurierbaren Wiederholungen getriggert werden. An Ports kann über <code>timeout</code> eine Überwachung konfiguriert werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation ist bindend für Werkzeuge und Generatoren zur Systembeschreibung (ARXML/FIBEX-Abbildung). Implementierer müssen beachten:</p>\n<ul class=\"fig-list\"><li>Ein <code>ISignalTriggering</code> referenziert zwingend genau ein <code>ISignal</code>, kann jedoch mehreren Ports zugeordnet sein.\n</li><li>Die Ausprägung von Timing-Mechanismen (<code>cyclicTiming</code>, <code>eventControlledTiming</code>) ist optional (Kardinalität <code>0..1</code>), schließt sich im Metamodell aber nicht gegenseitig aus.\n</li><li>Datentypen der Wiederholungszähler sind als <code>Int</code> und Timeouts als <code>Float</code> modelliert.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-cd3a9d8716abca97", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm des AUTOSAR-System-Templates (Bereich <code>CoreCommunication</code>). Das Metamodell definiert die Signalübertragung und das Timing-Verhalten auf Netzwerkebene durch <code>ISignalTriggering</code>. Es stellt die Verbindung zwischen Kommunikationsports, logischen Signalen und Auslöse-/Wiederholungsmechanismen her.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ISignalTriggering</code> (Spezialisierung von <code>Identifiable</code>): Zentrales Element zur Zuordnung und Auslösung eines Signals.\n<ul class=\"fig-list\"><li>Assoziation <code>+signal</code>: Genau eine Zielinstanz von <code>CoreCommunication::ISignal</code> (spezialisiert <code>FibexElement</code>); Rückrichtung mit Multiplizität <code>1..*</code>.\n</li><li>Assoziation <code>+iSignalPort</code>: Beliebig viele Instanzen (<code>*</code>) von <code>CoreCommunication::SignalPort</code> (spezialisiert <code>CommConnectorPort</code>).\n</li><li>Komposition <code>+eventControlledTiming 0..1</code>: Zielklasse <code>EventControlledTiming</code>.\n</li><li>Komposition <code>+cyclicTiming 0..1</code>: Zielklasse <code>CyclicTiming</code>.\n</li></ul>\n</li><li><code>SignalPort</code> (aus <code>CoreCommunication</code>):\n<ul class=\"fig-list\"><li>Attribut <code>+ timeout :Float [0..1]</code>.\n</li></ul>\n</li><li><code>ISignal</code> (aus <code>CoreCommunication</code>): Repräsentiert das Kommunikationssignal (<code>FibexElement</code>).\n</li><li><code>EventControlledTiming</code>:\n<ul class=\"fig-list\"><li>Attribut <code>+ numberOfRepeats :Integer</code>.\n</li></ul>\n</li><li><code>CyclicTiming</code>:\n<ul class=\"fig-list\"><li>Attribut <code>+ finalRepetitions :Integer [0..1]</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Darstellung dynamischer Sequenzen. Die Metaklassen beschreiben das Übertragungsverhalten von Signalen zur Laufzeit: Ein <code>ISignal</code> wird über <code>ISignalTriggering</code> an Ports (<code>SignalPort</code>) gebunden und kann entweder zyklisch (<code>CyclicTiming</code>) oder ereignisbasiert (<code>EventControlledTiming</code>) mit konfigurierbaren Wiederholungen getriggert werden. An Ports kann über <code>timeout</code> eine Überwachung konfiguriert werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation ist bindend für Werkzeuge und Generatoren zur Systembeschreibung (ARXML/FIBEX-Abbildung). Implementierer müssen beachten:</p>\n<ul class=\"fig-list\"><li>Ein <code>ISignalTriggering</code> referenziert zwingend genau ein <code>ISignal</code>, kann jedoch mehreren Ports zugeordnet sein.\n</li><li>Die Ausprägung von Timing-Mechanismen (<code>cyclicTiming</code>, <code>eventControlledTiming</code>) ist optional (Kardinalität <code>0..1</code>).\n</li><li>Attribute für Wiederholungszähler (<code>numberOfRepeats</code>, <code>finalRepetitions</code>) nutzen den AUTOSAR-Standardtyp <code>Integer</code>, Timeouts den Typ <code>Float</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-1dfc1b849ffda29d", "to": "FIG-fb4fa8449204bdbf", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-fb4fa8449204bdbf", "to": "FIG-cd3a9d8716abca97", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>EventControlledTiming</code>: Attribut <code>numberOfRepeats</code> ändert Datentyp von <code>Int</code> zu <code>Integer</code>.\n</li><li><code>CyclicTiming</code>: Attribut <code>finalRepetitions</code> ändert Datentyp von <code>Int</code> zu <code>Integer</code>.\n</li><li><code>ISignalTriggering</code>: Rollenbezeichnungen <code>cyclicTiming</code> und <code>eventControlledTiming</code> redaktionell durch Leerzeichen von der Multiplizität <code>0..1</code> getrennt.\n</li><li><code>SignalPort</code>: Attribut <code>timeout</code> redaktionell mit vorangestelltem Doppelpunkt formatiert (<code>:Float [0..1]</code>).\n</li></ul>"}]};
